using System;using System.IO;using System.Linq;using System.Windows;using System.Windows.Controls;using System.Collections.Generic;
public static class V11Tests {
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);}
 public static int Run(string folder){Directory.CreateDirectory(folder);var window=new MonitorWindow(true,new ArchiveStore(Path.Combine(folder,"archive")));try{
 window.ChooseServer(Storage.LocalServer());window.ChooseServer(Storage.DefaultServer());var m=Program.Fixture("eight");for(int i=0;i<60;i++)window.History.Add(new ResourceSample{Time=DateTime.UtcNow.AddSeconds((i-59)*5),Cpu=20+Math.Sin(i*.65)*9+i%9,Memory=50+Math.Sin(i*.2)*2});m.Hardware=new HardwareInfo{OperatingSystem="Ubuntu 22.04.5 LTS",CpuModel="Intel Xeon Gold 6138 · 双路处理器",PhysicalSockets=2,PhysicalCores=64,SystemThreads=128,AvailableThreads=124,MemoryBytes=512L*1024*1024*1024};m.Processes[0].User="baiyang";
 window.SetMetrics(m,false);window.SwitchView("GPU");window.RenderImage(Path.Combine(folder,"initial.png"),1440,960,96);string cpu=window.CpuValue.Text;var card=window.CardViews[0];window.SetMetrics(new Metrics{Error="模拟网络暂时中断"},false);Check(window.CpuValue.Text==cpu&&object.ReferenceEquals(window.CardViews[0],card),"Failure clears last valid metrics");Check(window.Connection.Text=="重连中","Failure state missing");window.ShowCompact();Check(window.CompactView.StateText.Contains("连接异常")&&window.CompactView.GpuCount==8,"Compact health and cached data mismatch");window.ApplyAppearance("light");Check(window.CompactView.StateText.Contains("连接异常"),"Theme lost failure state");window.CompactView.Hide();Check(window.TerminalButton.Foreground==Theme.Muted,"Header action theme mismatch");window.SwitchView("CPU");Check(window.Body.Children.Count>=2,"Hardware missing after failure");window.SetMetrics(m,false);
 CheckInspector(folder);var inventory=new List<string>();int count=0;foreach(string theme in new[]{"light","graphite","forest","ocean"}){window.ApplyAppearance(theme);window.SetMetrics(m,false);foreach(string page in new[]{"GPU","CPU","内存"})foreach(int width in new[]{760,1080,1440}){window.SwitchView(page);string name=theme+"-"+page+"-"+width;window.RenderImage(Path.Combine(folder,name+".png"),width,width==760?640:960,width==1080?144:96);UiReview.Record(window.Root,Path.Combine(folder,name+".csv"),name);var errors=window.Audit();Check(errors.Count==0,string.Join(";",errors));inventory.Add(name);count++;}}
 var toggleTransfers=typeof(MonitorWindow).GetMethod("ToggleTransfers",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);toggleTransfers.Invoke(window,null);window.RenderImage(Path.Combine(folder,"transfer-drawer.png"),1080,760,96);UiReview.Record(window.Root,Path.Combine(folder,"transfer-drawer.csv"),"transfer drawer");toggleTransfers.Invoke(window,null);
 window.SwitchView("CPU");window.ShowCores();Check(window.CoresExpanded,"Expand failed");window.ShowCores();Check(!window.CoresExpanded,"Collapse failed");
 var noGpu=Program.Fixture("none");window.SetMetrics(noGpu,false);window.SwitchView("GPU");window.RenderImage(Path.Combine(folder,"no-gpu.png"),1080,760,96);Check(window.CardViews.Count==0,"No GPU unsupported");File.WriteAllLines(Path.Combine(folder,"results.txt"),new[]{"PASS","UI_LAYOUTS="+count,"TRANSIENT_FAILURE_RETAINS_VALUES_AND_CARDS=PASS","HARDWARE_RETAINED=PASS","CORE_TOGGLE=PASS","NO_GPU=PASS","HEADER_ACTIONS_ALIGNED=PASS","TITLE_LABEL_BUTTON_INVENTORY=CSV per view","BOUNDARY=Synthetic display tests; actual SSH and terminal separately verified"});return 0;
 }finally{window.Exit();}}

 static void CheckInspector(string folder){using(var inspector=new TerminalInspector()){inspector.SetLocation(Storage.LocalServer(),folder);var deadline=DateTime.UtcNow.AddSeconds(8);while(inspector.CurrentPath==null&&DateTime.UtcNow<deadline){var frame=new System.Windows.Threading.DispatcherFrame();var timer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(30)};timer.Tick+=(a,b)=>{timer.Stop();frame.Continue=false;};timer.Start();System.Windows.Threading.Dispatcher.PushFrame(frame);}Check(inspector.CurrentPath!=null,"Inspector local directory did not load");inspector.SetLocation(new Server{Name="isolated-test",Host="127.0.0.1",Port=9,User="test",KeyPath=Path.Combine(folder,"missing-test-key")},"/other-device");Check(inspector.CurrentPath==null,"Inspector retained previous device directory");var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;Check(!((Button)typeof(TerminalInspector).GetField("uploadAction",flags).GetValue(inspector)).IsEnabled,"Inspector permits upload during device change");Check(!((Button)typeof(TerminalInspector).GetField("openAction",flags).GetValue(inspector)).IsEnabled,"Inspector permits opening old path during device change");}}
 public static async void NativeUI(Application app,string folder){Directory.CreateDirectory(folder);MonitorWindow window=null;try{window=new MonitorWindow(true,new ArchiveStore(Path.Combine(folder,"history")));window.ChooseServer(Storage.LocalServer());window.ChooseServer(Storage.DefaultServer());window.ApplyAppearance("light");var metrics=await System.Threading.Tasks.Task.Run(()=>Remote.Collect(Storage.DefaultServer()));if(!string.IsNullOrEmpty(metrics.Error))throw new Exception(metrics.Error);window.SetMetrics(metrics,false);window.RequestConnectionHealth(true);window.SwitchView("终端");window.ShowActivated=false;window.ShowInTaskbar=false;window.WindowStartupLocation=WindowStartupLocation.Manual;window.Left=-20000;window.Top=-20000;window.Width=1440;window.Height=960;window.Show();TerminalView view=null;for(int i=0;i<180;i++){await System.Threading.Tasks.Task.Delay(200);view=window.TerminalView.ActiveView;if(view!=null&&view.DiagnosticReady&&!string.IsNullOrEmpty(view.WorkingDirectory)&&!string.IsNullOrEmpty(window.TerminalView.FileInspector.CurrentPath))break;}if(view==null||!view.DiagnosticReady||string.IsNullOrEmpty(view.WorkingDirectory)||string.IsNullOrEmpty(window.TerminalView.FileInspector.CurrentPath))throw new Exception("Native terminal prompt or matching file location unavailable");foreach(string theme in new[]{"light","graphite"}){window.ApplyAppearance(theme);window.TerminalView.UpdateMetrics(Storage.DefaultServer(),metrics);await System.Threading.Tasks.Task.Delay(650);string baseFile=Path.Combine(folder,theme+"-terminal-shell.png");window.RenderImage(baseFile,1440,960,120);await System.Threading.Tasks.Task.Delay(700);string terminalFile=Path.Combine(folder,theme+"-terminal-webview.png");using(var stream=File.Create(terminalFile))await view.DiagnosticWeb.CoreWebView2.CapturePreviewAsync(Microsoft.Web.WebView2.Core.CoreWebView2CapturePreviewImageFormat.Png,stream);var point=view.DiagnosticWeb.TranslatePoint(new Point(0,0),window.Root);using(var scene=new System.Drawing.Bitmap(baseFile))using(var screen=System.Drawing.Image.FromFile(terminalFile))using(var painter=System.Drawing.Graphics.FromImage(scene)){painter.DrawImage(screen,new System.Drawing.Rectangle((int)Math.Round((point.X+24)*1.25),(int)Math.Round((point.Y+24)*1.25),(int)Math.Round(view.DiagnosticWeb.ActualWidth*1.25),(int)Math.Round(view.DiagnosticWeb.ActualHeight*1.25)));scene.Save(Path.Combine(folder,theme+"-terminal-composed.png"),System.Drawing.Imaging.ImageFormat.Png);}UiReview.Record(window.Root,Path.Combine(folder,theme+"-terminal-fonts.csv"),theme+" terminal");}
 window.SwitchView("CPU");for(int i=0;i<40;i++)window.History.Add(new ResourceSample{Time=DateTime.UtcNow.AddSeconds((i-39)*5),Cpu=i==39?ResourceSample.ParsePercent(metrics.Cpu):double.NaN,Memory=ResourceSample.MemoryPercent(metrics.Mem)});window.RenderImage(Path.Combine(folder,"native-cpu.png"),1440,960,120);window.SwitchView("GPU");window.RenderImage(Path.Combine(folder,"native-gpu.png"),1440,960,120);File.WriteAllText(Path.Combine(folder,"native-ui-results.txt"),"PASS\nREMOTE_GPU="+metrics.Gpus.Count+"\nCPU_THREADS="+metrics.Cores+"\nSYSTEM="+(metrics.Hardware==null?"":metrics.Hardware.OperatingSystem)+"\nSHELL="+view.State+"\nFILES="+window.TerminalView.FileInspector.CurrentPath+"\nNOTE=Terminal image combines native WPF RenderTargetBitmap and the actual WebView2 CapturePreview at its measured bounds. No fake terminal output.\n");window.Exit();app.Shutdown(0);}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"native-ui-error.txt"),ex.ToString());if(window!=null)window.Exit();app.Shutdown(1);}}
}
